#!/usr/bin/env python3
"""
apply_edit_disable.py  -  Letsma MSP Platform
------------------------------------------------------------------
Adds EDIT + DISABLE/ENABLE row actions to both the Recurring Billing
Catalogue and each customer's Recurring Billing list.

Run from the repo root (the folder containing `app/`):

    cd ~/Downloads/letsma-msp-platform/msp-app
    python apply_edit_disable.py

REQUIRES the catalogue feature to already be installed
(apply_catalogue_changes.py). This script:
  * Overwrites the 2 templates with Edit/Disable UI (byte-perfect).
  * Adds 2 new customer-item endpoints (update + toggle) to
    app/routers/recurring_billing.py.
Idempotent + backs up any Python file before editing.
"""
import base64, os, sys, shutil, datetime

APP = "app"
if not os.path.isdir(APP):
    print("ERROR: no 'app/' directory here. cd into the repo root (msp-app) first.")
    sys.exit(1)

def write_template(relpath, blob, label):
    path = os.path.join(APP, "templates", relpath)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    data = base64.b64decode(blob)
    with open(path, "wb") as f:
        f.write(data)
    print("  [template] wrote %s -> %s (%d bytes)" % (label, path, len(data)))

def backup(path):
    if os.path.exists(path):
        b = path + ".bak-" + datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
        shutil.copy2(path, b)
        print("  [backup]   %s -> %s" % (path, b))

def read(path):
    with open(path, "r", encoding="utf-8") as f:
        return f.read()

def write(path, content):
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)

CATALOG_HTML = ""
CUSTOMER_HTML = ""

RB_EDIT_CODE = '''

# ---- Customer recurring item edit/disable (added by apply_edit_disable.py) ----
@router.put("/api/customers/{customer_id}/recurring-billing/{item_id}")
def update_recurring_item(customer_id: str, item_id: str, payload: dict, db: Session = Depends(get_db)):
    item = db.query(_models.RecurringBillingItem).get(item_id)
    if not item or item.customer_id != customer_id:
        raise _HTTPException(404, "Recurring billing item not found")
    for field in ["description", "supplier_name", "billing_category", "quantity",
                  "cost_price", "sale_price", "billing_frequency", "notes"]:
        if field in payload:
            setattr(item, field, payload[field])
    if payload.get("next_invoice_date"):
        item.next_invoice_date = _date.fromisoformat(payload["next_invoice_date"])
    db.commit()
    return {"status": "ok"}


@router.patch("/api/customers/{customer_id}/recurring-billing/{item_id}/toggle")
def toggle_recurring_item(customer_id: str, item_id: str, db: Session = Depends(get_db)):
    item = db.query(_models.RecurringBillingItem).get(item_id)
    if not item or item.customer_id != customer_id:
        raise _HTTPException(404, "Recurring billing item not found")
    item.is_active = not item.is_active
    db.commit()
    return {"status": "ok", "is_active": item.is_active}
'''

print("\n== 1/2  Templates ==")
write_template("recurring_catalog.html", CATALOG_HTML, "recurring_catalog.html")
write_template("customer_recurring_billing.html", CUSTOMER_HTML, "customer_recurring_billing.html")

print("\n== 2/2  app/routers/recurring_billing.py ==")
rb_path = os.path.join(APP, "routers", "recurring_billing.py")
rb = read(rb_path)

if "/api/recurring-catalog" not in rb:
    print("  [ERROR]    catalogue endpoints not found - run apply_catalogue_changes.py FIRST.")
    sys.exit(1)

if "update_recurring_item" in rb:
    print("  [skip]     edit/disable endpoints already present")
else:
    backup(rb_path)
    write(rb_path, rb.rstrip() + "\n" + RB_EDIT_CODE)
    print("  [add]      appended update_recurring_item + toggle_recurring_item endpoints")

print("\n== Verifying ==")
try:
    import ast
    ast.parse(read(rb_path))
    print("  recurring_billing.py: valid Python syntax")
except SyntaxError as e:
    print("  [ERROR] syntax error:", e)
    sys.exit(1)

print("""
==================================================================
 DONE. Next steps:

   git add -A
   git commit -m "Add edit/disable for recurring billing + catalogue"
   git checkout main && git pull origin main
   git merge add-email-to-ticket
   git push origin main
   git checkout add-email-to-ticket

 No database migration needed - this change is code/UI only.
==================================================================
""")
